68	/// Represents a savepoint on a database connection.
69	///
70	/// ## Note
71	///
72	/// Savepoints will roll back by default. Use `commit` method to explicitly
73	/// commit the savepoint, or use `set_drop_behavior` to change what happens
74	/// when the savepoint is dropped.
75	///
76	/// ## Example
77	///
78	/// ```rust,no_run
79	/// # use rusqlite::{Connection, Result};
80	/// # fn do_queries_part_1(_conn: &Connection) -> Result<()> { Ok(()) }
81	/// # fn do_queries_part_2(_conn: &Connection) -> Result<()> { Ok(()) }
82	/// fn perform_queries(conn: &mut Connection) -> Result<()> {
83	///     let sp = conn.savepoint()?;
84	///
85	///     do_queries_part_1(&sp)?; // sp causes rollback if this fails
86	///     do_queries_part_2(&sp)?; // sp causes rollback if this fails
87	///
88	///     sp.commit()
89	/// }
90	/// ```
91	#[derive(Debug)]
92	pub struct Savepoint<'conn> {
93	    conn: &'conn Connection,
94	    name: String,
95	    drop_behavior: DropBehavior,
96	    committed: bool,
97	}
