359	fn cmd(cmd: &'static str, to: bool, name: &str) -> Result<Sql> {
360	    let mut sql = Sql::new();
361	    sql.push_keyword(cmd)?;
362	    sql.push_space();
363	    if to {
364	        sql.push_keyword("TO")?;
365	        sql.push_space();
366	    }
367	    sql.push_identifier(name);
368	    Ok(sql)
369	}
