577	    fn test_drop() -> Result<()> {
578	        let mut db = checked_memory_handle()?;
579	        {
580	            let tx = db.transaction()?;
581	            tx.execute_batch("INSERT INTO foo VALUES(1)")?;
582	            // default: rollback
583	        }
584	        {
585	            let mut tx = db.transaction()?;
586	            tx.execute_batch("INSERT INTO foo VALUES(2)")?;
587	            tx.set_drop_behavior(DropBehavior::Commit);
